// Returns true iff `v` starts with prefix `p`.
// By definition: empty prefix always matches; otherwise `v` must be at least as long
// and all characters up to `p.len()` must be equal.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

// Filters `xs`, keeping exactly those sequences that start with `p`,
// preserving their original relative order.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered: Vec<Vec<char>> = Vec::new();
    for v in xs.into_iter() {
        if has_prefix(&v, &p) {
            filtered.push(v);
        }
    }
    filtered
}